(function(root){
'use strict';const C=HoorContent,M=HoorModel,esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
class Mission{
 constructor(host,onExit){this.host=host;this.onExit=onExit;this.s=M.create();this.error=false;try{const raw=localStorage.getItem(M.key);if(raw)this.s=M.decode(raw)}catch{this.error=true}this.abort=new AbortController();this.host.addEventListener('click',e=>this.click(e),{signal:this.abort.signal});window.addEventListener('keydown',e=>{if(['Enter',' '].includes(e.key)&&!['BUTTON','INPUT','A'].includes(e.target.tagName)&&!this.host.querySelector('dialog[open]')&&Array.isArray(C[this.s.stage])){e.preventDefault();M.next(this.s);this.save();this.render()}},{signal:this.abort.signal});document.body.classList.add('hoor-active');this.render();this.save()}
 save(){try{localStorage.setItem(M.key,JSON.stringify(this.s));this.error=false}catch{this.error=true}}
 destroy(){this.save();clearTimeout(this.timer);this.abort.abort();document.body.classList.remove('hoor-active')}
 talk(name,text){const who={محمد:'player',یونس:'younes',پورشریفی:'mentor'}[name]||'younes';return `<div class="hoor-dialogue"><div class="hoor-person">${GameArt.portrait(who,who==='player'?'front':'neutral')}</div><div><h2>${name}</h2><p>${esc(text)}</p></div></div>`}
 quiz(){const q=C.quizzes[this.s.stage];return `<div class="hoor-question"><p>یونس: ${q.question}</p><div class="hoor-options">${q.options.map((v,i)=>`<button data-answer="${i}">${esc(v)}</button>`).join('')}</div></div>`}
 render(){const s=this.s,indoor=['brief','report','complete'].includes(s.stage);let body='',next='',title='شناسایی مهندسی در هور';if(Array.isArray(C[s.stage])){const [name,text]=C[s.stage][s.line];body=this.talk(name,text);next='ادامه';if(s.stage==='dock')title='اسکله قرارگاه';if(s.stage==='brief')title='دریافت مأموریت';if(s.stage==='fieldIntro')title='در مسیر ب';if(s.stage==='report')title='ارائه گزارش';}
 else if(s.stage==='route'){title='مقایسه مسیرها';body=`<div class="route-layout"><svg class="hoor-route-map" viewBox="0 0 440 240" role="img" aria-label="نقشه شماتیک سه مسیر هم‌ارز"><rect width="440" height="240" rx="15" fill="#456b60"/>${['الف','ب','ج'].map((v,i)=>`<path d="M 30 ${50+i*65} Q 150 ${20+i*55} 230 ${60+i*50} T 405 ${45+i*70}" stroke="#e6ce8a" fill="none" stroke-width="4" stroke-dasharray="8 6"/><text x="220" y="${36+i*70}" fill="#fff1cb" font-size="20" text-anchor="middle">مسیر ${v}</text>`).join('')}</svg><div class="route-cards">${M.routes.map((r,i)=>`<article><h3>مسیر ${r[0]}</h3><dl>${['طول','عمق','بستر','پوشش','جریان'].map((k,n)=>`<div><dt>${k}</dt><dd>${r[n+1]}</dd></div>`).join('')}</dl><button data-route="${['a','b','c'][i]}" ${s.feedback?'disabled':''}>انتخاب مسیر ${r[0]}</button></article>`).join('')}</div></div>`;if(s.feedback)next=s.success?'شروع شناسایی میدانی':'بررسی دوباره نقشه'}
 else if(s.stage==='measure'){title='اندازه‌گیری سه نقطه';body=`<div class="hoor-measure"><button data-h="tool" class="rod-tool ${s.tool?'selected':''}"><i></i>انتخاب میله مدرج</button><div class="hoor-points">${M.depth.map((d,i)=>`<button data-point="${i}" class="${s.points[i]?'measured':''}"><span>نقطه ${i+1}</span>${s.points[i]?`بررسی شد<small>${d} سانتی‌متر<br>گل متراکم · نیزار پراکنده</small>`:'برای اندازه‌گیری لمس کن'}</button>`).join('')}</div></div>`;if(s.points.every(Boolean)&&!s.success)body+=this.quiz();if(s.success)next='شروع بررسی‌های تکمیلی'}
 else if(s.stage==='bed'){title='آزمایش مقاومت بستر';body=`<div class="bed-test"><div class="rod-water"><div class="graduated-rod" style="transform:translateY(${s.observed*14}px)"></div><div class="mud-bed"></div></div><div><button data-h="pressure" ${s.observed===2?'disabled':''}>${s.observed===0?'اعمال فشار متوسط':'اعمال فشار بیشتر'}</button><p>${s.observed>=1?'فشار متوسط: ۱۸ سانتی‌متر':''}</p><p>${s.observed===2?'فشار بیشتر: ۲۶ سانتی‌متر':''}</p></div></div>`;if(s.observed===2)body+=this.quiz()}
 else if(s.stage==='flow'){title='اندازه‌گیری جریان آب';body=`<div class="flow-test"><div class="flow-track"><span class="float-marker ${this.busy?'moving':s.flowObserved?'arrived':''}"></span><span>شروع</span><span>۴ متر</span></div><button data-h="flow" ${this.busy?'disabled':''}>${this.busy?'در حال اندازه‌گیری…':'رها کردن نشانگر'}</button><p>${s.flowObserved?'نشانگر در ۲۰ ثانیه، ۴ متر حرکت می‌کند.':'نمایش زمان با سرعت ۵ برابر؛ ۴ ثانیه نمایش = ۲۰ ثانیه آزمایش فرضی'}</p></div>`;if(s.flowObserved)body+=this.quiz()}
 else if(s.stage==='float'){title='آزمایش پایداری نمونه‌ها';body=`<div class="float-models">${[['الف','بدون مهار جانبی','۴۰',40],['ب','مهار از دو طرف','۸',8],['ج','مهار از یک طرف','۲۵',25]].map(([n,label,dist,x])=>`<article><h3>مدل ${n}</h3><div class="float-water ${this.busy?'run':''}" style="--drift:${x}px"><i class="float-piece"></i>${n!=='الف'?'<span class="tie left"></span>':''}${n==='ب'?'<span class="tie right"></span>':''}</div><p>${label}</p><p>${s.floatObserved?dist+' سانتی‌متر':'هنوز آزمایش نشده'}</p></article>`).join('')}</div><button data-h="float" ${this.busy?'disabled':''}>${this.busy?'آزمایش در جریان است':'آزمایش هر سه مدل'}</button>`;if(s.floatObserved)body+=this.quiz()}
 else if(s.stage==='summary'){title='جمع‌بندی شناسایی';body=this.talk('یونس',C.summary);next='بازگشت به قرارگاه'}
 else if(s.stage==='complete'){title='مأموریت شناسایی تکمیل شد.';body='<div class="hoor-complete"><span>✓</span><h2>مأموریت شناسایی تکمیل شد.</h2><p>مرحله بعدی: طراحی و ساخت نمونه پل خیبر</p><p>گزارش محمد ثبت شد. فصل سوم از صفحه عملیات در دسترس است.</p></div>';next='بازگشت به عملیات'}
 this.host.innerHTML=`<section class="hoor-mission ${indoor?'indoor':''}" dir="rtl"><header class="hoor-heading"><div><small>عملیات خیبر · فصل دوم</small><h1>${title}</h1></div><div><button data-h="journal">دفترچه محمد</button><button data-h="export">خروجی ذخیره</button><button data-h="import">ورود ذخیره</button><button data-h="exit">هسته بازی</button></div></header><div class="hoor-content ${s.stage}">${body}</div><div class="hoor-feedback" role="status">${s.feedback?esc((s.stage==='measure'&&!s.points.every(Boolean)?'':'یونس: ')+s.feedback):''}</div><div class="hoor-bottom"><small>${this.error?'ذخیره مرورگر ممکن نیست؛ خروجی بگیر':'پیشرفت خودکار ذخیره می‌شود'} · داده‌ها فرضی‌اند</small>${next?`<button class="primary" data-h="next">${next}</button>`:''}</div><dialog id="hoorJournal"></dialog></section>`;
 }
 click(e){const b=e.target.closest('button');if(!b||b.disabled)return;const s=this.s;if(b.dataset.route){M.chooseRoute(s,b.dataset.route)}else if(b.dataset.point!==undefined){M.measure(s,Number(b.dataset.point))}else if(b.dataset.answer!==undefined){M.answer(s,Number(b.dataset.answer))}else switch(b.dataset.h){case 'next':if(s.stage==='complete'){this.destroy();this.onExit(true);return}if(s.stage==='route'&&!s.success)s.feedback='';else M.next(s);break;case 'tool':s.tool=true;s.feedback='میله مدرج انتخاب شد؛ یک نقطه را بررسی کن.';break;case 'pressure':s.observed=Math.min(2,s.observed+1);break;case 'flow':case 'float':{this.busy=true;const key=b.dataset.h;clearTimeout(this.timer);this.timer=setTimeout(()=>{this.busy=false;s[key==='flow'?'flowObserved':'floatObserved']=true;this.save();this.render()},4000);break}case 'exit':this.destroy();this.onExit(false);return;case 'journal':{const d=this.host.querySelector('dialog');d.innerHTML='<h2>دفترچه محمد</h2><p>اعداد این دفترچه داده‌های فرضی طراحی گیم‌پلی هستند و سند اندازه‌گیری تاریخی نیستند.</p>'+s.journal.map(x=>'<p>'+esc(x)+'</p>').join('')+'<button data-h="close">بستن دفترچه</button>';d.showModal();return}case 'close':this.host.querySelector('dialog').close();return;case 'export':{const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(s)],{type:'application/json'}));a.href=url;a.download='sangarsazan-hoor02-save.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return}case 'import':{const input=document.createElement('input');input.type='file';input.accept='.json';input.onchange=async()=>{try{if(input.files[0].size>100000)throw Error();this.s=M.decode(await input.files[0].text());this.save();this.render()}catch{s.feedback='فایل ذخیره نامعتبر است؛ پیشرفت قبلی حفظ شد.';this.render()}};input.click();return}}this.save();this.render()
 }
}
root.HoorMission={mount:(host,onExit)=>new Mission(host,onExit)};
})(globalThis);
